for m in moves:
    aw=simulate_move(fen,m)
    t=terminal_score(aw)
    if t is not None:
        sc=t
    else:
        reps=aw['legal_moves']
        if not reps:
            sc=eval_fen(aw['fen'])
        else:
            scs=[]
            for rep in reps:
                ab=simulate_move(aw['fen'],rep)
                t2=terminal_score(ab)
                scs.append(t2 if t2 is not None else eval_fen(ab['fen']))
            sc=min(scs)
